def distinct_subsequences(S):
    n = len(S)
    dp = {S[0]: 1}
    for i in range(1, n):
        for j in dp:
            if S[i] == j:
                dp[j] += 1
            else:
                dp[j + S[i]] = dp.get(j + S[i], 0) + 1
    return sum(dp.values()) % (10**9 + 7)
